// We use Verus for specification and verification
use vstd::prelude::*;

// solve: Given a four‐digit integer n in [1000,9999], determine whether
// either its first three digits are all equal or its last three digits
// are all equal.
//
// We extract the digits as:
//   d1 = thousands digit
//   d2 = hundreds digit
//   d3 = tens digit
//   d4 = ones digit
// and then check (d1==d2 && d2==d3) || (d2==d3 && d3==d4).

verus! {
    // We choose i32 for n so we can express the range [1000,9999].
    // If you must stick with i8, you could reinterpret n as u16 internally,
    // but i8 cannot represent 1000..9999 directly.
    fn solve(n: i32) -> bool
        // Precondition: n is a four‐digit decimal integer
        requires 1000 <= n && n <= 9999
        // Postcondition: the return value is true exactly when either
        // the first three digits or the last three digits of n are equal
        ensures |res: bool|
            res ==
            ({
                let d1 = n / 1000;           // thousands
                let d2 = (n / 100) % 10;     // hundreds
                let d3 = (n / 10) % 10;      // tens
                let d4 = n % 10;             // ones
                (d1 == d2 && d2 == d3) || (d2 == d3 && d3 == d4)
            })
    {
        // Extract digits
        let d1: i32 = n / 1000;          // thousands place
        let d2: i32 = (n / 100) % 10;    // hundreds place
        let d3: i32 = (n / 10) % 10;     // tens place
        let d4: i32 = n % 10;            // ones place

        // Check the two patterns
        (d1 == d2 && d2 == d3) || (d2 == d3 && d3 == d4)
    }

    // A few quick proof tests
    proof fn test_positive_cases() {
        assert!( solve(1112) == true );  // first three equal
        assert!( solve(2111) == true );  // last three equal
        assert!( solve(2222) == true );  // both
        assert!( solve(1233) == false ); // neither
        assert!( solve(3444) == true );  // last three equal
        assert!( solve(5556) == true );  // first three equal
    }
}